INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'health-nutrition' LIMIT 1), 'PROBIOTICS ORAL HEALTH', 'ru-2026-probiotics-oral-health-501615', '501615', @catalog_source, 6, 'supplement', 'catalog_only', 'candidate', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Специально культивируемые моноштаммы Lactobacillus plantarum и Lactobacillus acidophilus для сохранения баланса микрофлоры полости рта. Как работает формула: • укрепляет зубную эмаль, поддерживает здоровье десен и зубов, снижает риск развития кариеса; • активизирует местные защитные функции полости рта и защищает от воспаления в носоглотке; • улучшает свежесть дыхания и способствует росту здоровых бактерий полости рта.', 'PROBIOTICS ORAL HEALTH Специально культивируемые моноштаммы Lactobacillus plantarum и Lactobacillus acidophilus для сохранения баланса микрофлоры полости рта. Как работает формула: • укрепляет зубную эмаль, поддерживает здоровье десен и зубов, снижает риск развития кариеса; • активизирует местные защитные функции полости рта и защищает от воспаления в носоглотке; • улучшает свежесть дыхания и способствует росту здоровых бактерий полости рта. | 30 таблеток 1450 ₽ Штаммы LAB2PRO™ от Cell Biotech (Ю. Корея) защищены от воздействия Дмитрий Алексеев окружающей среды благодаря специальной системе, повышающей кандидат биологических наук, выживаемость бактерий. микробиолог, доцент СКФУ «Микробиом полости рта — второй по числен- ности в человеческом организме. Его влияние на здоровье организма очень широко: от под- держки пищеварения до функций сердца, Внутренняя Внешняя защита штаммов сосудов и нервной системы. защита штаммов повышает стабильность Баланс микрофлоры полости рта — ключ на протяжении во время производства к эффективной превенции серьезных проблем всего ЖКТ. и на протяжении всего со здоровьем». срока годности.', NULL, 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Специально культивируемые моноштаммы Lactobacillus plantarum и Lactobacillus acidophilus для сохранения баланса микрофлоры полости рта. Как работает формула: • укрепляет зубную эмаль, поддерживает здоровье десен и зубов, снижает риск развития кариеса; • активизирует местные защитные функции полости рта и защищает от воспаления в носоглотке; • улучшает свежесть дыхания и способствует росту здоровых бактерий полости рта.', 'Каталог Siberian Wellness RU 2026, стр. PDF 6', '/admin/uploads/products/catalog-2026/ru-2026-probiotics-oral-health-501615.webp', 1450, 0, 'review', 1, 1007) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
