лорид, хондроитинсульфат. * Указан активный состав без учета вспомогательных компонентов.', 'Каталог Siberian Wellness RU 2026, стр. PDF 12', '/admin/uploads/products/catalog-2026/ru-2026-d-flex-cube-svoboda-dvijenij-500570.webp', NULL, 0, 'review', 1, 1013) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
