INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'health-nutrition' LIMIT 1), 'ХРУСТЯЩИЕ ШАРИКИ С КАКАО-МАСЛОМ МАЛИНА', 'ru-2026-hrustasie-sariki-s-kakao-maslom-malina-500670', '500670', @catalog_source, 46, 'supplement', 'catalog_only', 'candidate', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Всего горсть хрустящих шариков быстро утоляет голод и надолго заряжает энергией!', 'СУПЕРСИЛА 134 мг ОРГАНИЧЕСКОГО ДЛЯ РОСТА КАЛЬЦИЯ В ПОРЦИИ И КРЕПКИХ ЗУБО ХРУСТЯЩИЕ ШАРИКИ С КАКАО-МАСЛОМ МАЛИНА Всего горсть хрустящих шариков быстро утоляет голод и надолго заряжает энергией! Состав: какао-масло, молоко сухое, изомальтулоза Палатиноза™, cибирские отруби хрустящие «Сила ягод» (отруби пшеничные пищевые, мука ржаная (содержат глютен), плоды шиповника, сушеные ягоды клюквы и черники), порошок фруктовый из малины (глюкозный сироп, малина, сок свекольный концентрированный), морские минерализованные водоросли, глянцеватель «Квик-шайн» (содержит глютен), ароматизатор пищевой натуральный «Клуб- ника», ароматизатор пищевой натуральный. 70 г 650 ₽', 'какао-масло, молоко сухое, изомальтулоза Палатиноза™, cибирские отруби хрустящие «Сила ягод» (отруби пшеничные пищевые, мука ржаная (содержат глютен), плоды шиповника, сушеные ягоды клюквы и черники), порошок фруктовый из малины (глюкозный сироп, малина, сок свекольный концентрированный), морские минерализованные водоросли, глянцеватель «Квик-шайн» (содержит глютен), ароматизатор пищевой натуральный «Клуб- ника», ароматизатор пищевой натуральный.', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Всего горсть хрустящих шариков быстро утоляет голод и надолго заряжает энергией!', 'Каталог Siberian Wellness RU 2026, стр. PDF 46', '/admin/uploads/products/catalog-2026/ru-2026-hrustasie-sariki-s-kakao-maslom-malina-500670.webp', NULL, 0, 'review', 1, 1119) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
