INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'health-nutrition' LIMIT 1), 'CORENRG УНИВЕРСАЛЬНЫЙ ИММУНОБУСТЕР', 'ru-2026-corenrg-universal-nyj-immunobuster-500327', '500327', @catalog_source, 50, 'supplement', 'catalog_only', 'candidate', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Быстрое и удобное решение при стрессах и простуде, смене часовых поясов и кли- матических зон, экзаменах и тяжелой работе, экологических и токсических нагрузках, упадке сил и плохом настрое- нии, любых хронических истощающих состояниях.', 'это мощный концентрат сока пихты, усиленный экстрактами сибирских адаптогенных растений. В каждой капле — сила всей сибирской тайги! CORENRG УНИВЕРСАЛЬНЫЙ ИММУНОБУСТЕР Быстрое и удобное решение при стрессах и простуде, смене часовых поясов и кли- матических зон, экзаменах и тяжелой работе, экологических и токсических нагрузках, упадке сил и плохом настрое- нии, любых хронических истощающих состояниях. Состав: вода, клеточный концентрат сибирской пихты Bioeffective™ by Prenolica™, растительный комплекс CoreNRG (экстракты красной щетки, курильского чая, чабреца, зверо- боя, солянки холмовой), комплекс растительных экстрактов сибирских эндемиков (экстракты элеутерококка, маральего корня, байкальского шлемника). 30 мл 970 ₽ БЕЗ САХАРА | БЕЗ КОФЕИНА | БЕЗ ТАУРИНА', 'вода, клеточный концентрат сибирской пихты Bioeffective™ by Prenolica™, растительный комплекс CoreNRG (экстракты красной щетки, курильского чая, чабреца, зверо- боя, солянки холмовой), комплекс растительных экстрактов сибирских эндемиков (экстракты элеутерококка, маральего корня, байкальского шлемника).', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Быстрое и удобное решение при стрессах и простуде, смене часовых поясов и кли- матических зон, экзаменах и тяжелой работе, экологических и токсических нагрузках, упадке сил и плохом настрое- нии, любых хронических истощающих состояниях.', 'Каталог Siberian Wellness RU 2026, стр. PDF 50', '/admin/uploads/products/catalog-2026/ru-2026-corenrg-universal-nyj-immunobuster-500327.webp', NULL, 0, 'review', 1, 1144) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
