INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'health-nutrition' LIMIT 1), 'CORENRG ЖЕВАТЕЛЬНЫЙ МАРМЕЛАД С ПРОПОЛИСОМ', 'ru-2026-corenrg-jevatel-nyj-marmelad-s-propolisom-500563', '500563', @catalog_source, 50, 'supplement', 'catalog_only', 'candidate', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у консультанта или специалиста.', 'Жевательный мармелад CoreNRG с натуральным прополисом — терпко, вкусно, полезно! Зарядитесь энергией сибирской тайги и забудьте об обычных сладостях!', 'CORENRG ЖЕВАТЕЛЬНЫЙ МАРМЕЛАД С ПРОПОЛИСОМ Жевательный мармелад CoreNRG с натуральным прополисом — терпко, вкусно, полезно! Зарядитесь энергией сибирской тайги и забудьте об обычных сладостях! Состав: фруктоза, вода, желатин говяжий, патока крахмальная карамельная, мед натуральный, лимонная кислота (регулятор кислотности), экстракт прополиса густой, глазирователь Capol® (воск карнаубский, растительное масло), глазирователь Эмуль- сифайн 1000 (шеллак, растительное масло), карамелизованный сахарный сироп, бензойная и сорбиновая кислоты (консерванты). 90 г 370 ₽ ЗАЩИТИТЕСЬ ОСТАВАЙТЕСЬ ДЫШИТЕ ОТ ИНФЕКЦИЙ БОДРЫМИ СВОБОДНО', 'фруктоза, вода, желатин говяжий, патока крахмальная карамельная, мед натуральный, лимонная кислота (регулятор кислотности), экстракт прополиса густой, глазирователь Capol® (воск карнаубский, растительное масло), глазирователь Эмуль- сифайн 1000 (шеллак, растительное масло), карамелизованный сахарный сироп, бензойная и сорбиновая кислоты (консерванты).', 'Информация носит ознакомительный характер. Перед применением уточните способ приёма, ограничения и совместимость у к