INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'face-care' LIMIT 1), 'CHRONOLONG КРЕМ НОЧНОЙ С ФИТОЭСТРОГЕНАМ', 'ru-2026-chronolong-krem-nocnoj-s-fitoestrogenam-427558', '427558', @catalog_source, 66, 'cosmetic', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Интенсивно увлажняет и питает кожу без ощущения тяжести, даря ей молодос и здоровое сияние на следующее утро. Повышает плотность и упругость кожи изнутри, уменьшает видимость мимич морщин. Результат: подтянутый овал лица и гладкая кожа.', 'CHRONOLONG КРЕМ НОЧНОЙ С ФИТОЭСТРОГЕНАМ Интенсивно увлажняет и питает кожу без ощущения тяжести, даря ей молодос и здоровое сияние на следующее утро. Повышает плотность и упругость кожи изнутри, уменьшает видимость мимич морщин. Результат: подтянутый овал лица и гладкая кожа. 50 мл 1', NULL, NULL, 'Интенсивно увлажняет и питает кожу без ощущения тяжести, даря ей молодос и здоровое сияние на следующее утро. Повышает плотность и упругость кожи изнутри, уменьшает видимость мимич морщин. Результат: подтянутый овал лица и гладкая кожа.', 'Каталог Siberian Wellness RU 2026, стр. PDF 66', '/admin/uploads/products/catalog-2026/ru-2026-chronolong-krem-nocnoj-s-fitoestrogenam-427558.webp', NULL, 1, 'approved', 1, 1193) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
