INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'face-care' LIMIT 1), 'ИННОВАЦИОННЫЙ КОМПЛЕКС BIOMELLE', 'ru-2026-innovacionnyj-kompleks-biomelle-108371', '108371', @catalog_source, 79, 'cosmetic', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', '• Ecoskin® — пре- и пробиотик, экологичный усилитель красоты кожи. • Пробиотический антивозрастной подход к обновлению кожи. • Арабиногалактан — пребиотик из сибирской лиственницы, способствует ускорению самовосстановления кожи. • Витамин С — мощный антиоксидант, усиливающий иммунитет кожи и улучшающий цвет лица. * По результатам тестов in vivo активных компонентов серии. КОСМЕТИ ** МИКРОБИОМ — совокупность микроорганизмов, которые живут на поверхности кожи и находятся в симбиозе с организмом человека. Чем разнообразнее состав этих микроорганизмов — тем лучше для здоровья нашей кожи. 154', 'ИННОВАЦИОННЫЙ КОМПЛЕКС BIOMELLE: • Ecoskin® — пре- и пробиотик, экологичный усилитель красоты кожи. • Пробиотический антивозрастной подход к обновлению кожи. • Арабиногалактан — пребиотик из сибирской лиственницы, способствует ускорению самовосстановления кожи. • Витамин С — мощный антиоксидант, усиливающий иммунитет кожи и улучшающий цвет лица. * По результатам тестов in vivo активных компонентов серии. КОСМЕТИ ** МИКРОБИОМ — совокупность микроорганизмов, которые живут на поверхности кожи и находятся в симбиозе с организмом человека. Чем разнообразнее состав этих микроорганизмов — тем лучше для здоровья нашей кожи. 154', NULL, NULL, '• Ecoskin® — пре- и пробиотик, экологичный усилитель красоты кожи. • Пробиотический антивозрастной подход к обновлению кожи. • Арабиногалактан — пребиотик из сибирской лиственницы, способствует ускорению самовосстановления кожи. • Витамин С — мощный антиоксидант, усиливающий иммунитет кожи и улучшающий цвет лица. * По результатам тестов in vivo активных компонентов серии. КОСМЕТИ ** МИКРОБИОМ — совокупность микроорганизмов, которые живут на поверхности кожи и находятся в симбиозе с организмом человека. Чем разнообразнее состав этих микроорганизмов — тем лучше для здоровья нашей кожи. 154', 'Каталог Siberian Wellness RU 2026, стр. PDF 79', '/admin/uploads/products/catalog-2026/ru-2026-innovacionnyj-kompleks-biomelle-108371.webp', NULL, 1, 'approved', 1, 1230) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
