INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'hair-care' LIMIT 1), 'ШАМПУНЬ ДЛЯ РОСТА ВОЛОС С НИАЦИНАМИДОМ И ПЕРЦЕМ', 'ru-2026-sampun-dla-rosta-volos-s-niacinamidom-i-percem-424442', '424442', @catalog_source, 108, 'personal_care', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Шампунь эффективно очищает и стимулирует кровообращение в коже головы, способствует укре- плению и росту сильных, здоровых волос. Мощная сбалансированная формула восстанавливает струк- туру волос, снижает ломкость, придавая укладке дополнительный объем.', 'КАСТОРОВОЕ МАСЛО Глубоко проникает в структуру волос, уплотняя их изнутри и придавая потрясающую гладкость и блеск. Благодаря противомикробному и бактери- цидному действию помогает справиться с зудом и шелушением. РИЦИНОЛЕВАЯ КИСЛОТА Улучшает микроциркуляцию и обменные процессы в коже головы, благотворно влияя на рост волос. МЕНТОЛ Улучшает микроциркуляцию крови в коже, тонизи- рует, нормализует жирность и предотвращает появ- ление перхоти. ШАМПУНЬ ДЛЯ РОСТА ВОЛОС С НИАЦИНАМИДОМ И ПЕРЦЕМ Шампунь эффективно очищает и стимулирует кровообращение в коже головы, способствует укре- плению и росту сильных, здоровых волос. Мощная сбалансированная формула восстанавливает струк- туру волос, снижает ломкость, придавая укладке дополнительный объем. 250 мл 450 ₽ 212', NULL, NULL, 'Шампунь эффективно очищает и стимулирует кровообращение в коже головы, способствует укре- плению и росту сильных, здоровых волос. Мощная сбалансированная формула восстанавливает струк- туру волос, снижает ломкость, придавая укладке дополнительный объем.', 'Каталог Siberian Wellness RU 2026, стр. PDF 108', '/admin/uploads/products/catalog-2026/ru-2026-sampun-dla-rosta-volos-s-niacinamidom-i-percem-424442.webp', NULL, 1, 'approved', 1, 1347) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
