INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'hair-care' LIMIT 1), 'ШАМПУНЬ ПРОТИВ ПЕРХОТИ ШАЛФЕЙ И ЯНТАРНАЯ КИСЛОТА', 'ru-2026-sampun-protiv-perhoti-salfej-i-antarnaa-kislota-427524', '427524', @catalog_source, 108, 'personal_care', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Эффективный шампунь с пироктоном оламином, маслами шалфея, можжевельника и туи очищает волосы и кожу головы, устраняя причины появ- ления перхоти. Уменьшает секрецию кожного сала, предотвращает раздражение и шелушение кожи, позволяя надолго сохранить ощущение чистоты и легкости после мытья.', 'Обладает антиоксидантными и регенерирую- щими свойствами, уплотняет стержень волоса изнутри, улучшая его внешний вид. Активирует рост волос, благотворно влияет на кожу головы, улучшая обменные процессы в клетках. РАСТИТЕЛЬНЫЕ МАСЛА И ЭКСТРАКТЫ Эфирные масла можжевеловых ягод и туи ба- лансируют выделение кожного сала, помогают уменьшить шелушение кожи и ускоряют обмен- ные процессы. Экстракт бадана работает как мощный антисептик и восстанавливает волосяные луковицы. ШАМПУНЬ ПРОТИВ ПЕРХОТИ ШАЛФЕЙ И ЯНТАРНАЯ КИСЛОТА Эффективный шампунь с пироктоном оламином, маслами шалфея, можжевельника и туи очищает волосы и кожу головы, устраняя причины появ- ления перхоти. Уменьшает секрецию кожного сала, предотвращает раздражение и шелушение кожи, позволяя надолго сохранить ощущение чистоты и легкости после мытья. 250 мл 450 ₽', NULL, NULL, 'Эффективный шампунь с пироктоном оламином, маслами шалфея, можжевельника и туи очищает волосы и кожу головы, устраняя причины появ- ления перхоти. Уменьшает секрецию кожного сала, предотвращает раздражение и шелушение кожи, позволяя надолго сохранить ощущение чистоты и легкости после мытья.', 'Каталог Siberian Wellness RU 2026, стр. PDF 108', '/admin/uploads/products/catalog-2026/ru-2026-sampun-protiv-perhoti-salfej-i-antarnaa-kislota-427524.webp', NULL, 1, 'approved', 1, 1348) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
