INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'body-care' LIMIT 1), 'МАСКА ДЛЯ ЛИЦА', 'ru-2026-maska-dla-lica-424406', '424406', @catalog_source, 113, 'personal_care', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Маска с троксерутином активно ув- лажняет кожу, помогает улучшению микроциркуляции и сужению сосудов. Возвращает коже эластичность и барха- тистость.', 'сип соосхорбаснтевнуиюют пчоевткыошгое ноивюал уап лриуцгоас, тбио - рются с отеками и следами усталости. 50 мл 800 ₽ МАСКА ДЛЯ ЛИЦА Маска с троксерутином активно ув- лажняет кожу, помогает улучшению микроциркуляции и сужению сосудов. Возвращает коже эластичность и барха- тистость. 50 мл 800 ₽', NULL, NULL, 'Маска с троксерутином активно ув- лажняет кожу, помогает улучшению микроциркуляции и сужению сосудов. Возвращает коже эластичность и барха- тистость.', 'Каталог Siberian Wellness RU 2026, стр. PDF 113', '/admin/uploads/products/catalog-2026/ru-2026-maska-dla-lica-424406.webp', NULL, 1, 'approved', 1, 1369) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowe