INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'body-care' LIMIT 1), 'ГЕЛЬ ДЛЯ ДУША', 'ru-2026-gel-dla-dusa-424407', '424407', @catalog_source, 114, 'personal_care', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Гель с арктическими водорослями, пантенолом и коллагеном глубоко и бережно очищает кожу тела. Интенсивно увлажняет и спо- собствует поддержанию водного баланса, обновляет, тонизирует', 'ГЕЛЬ ДЛЯ ДУША Гель с арктическими водорослями, пантенолом и коллагеном глубоко и бережно очищает кожу тела. Интенсивно увлажняет и спо- собствует поддержанию водного баланса, обновляет, тонизирует', NULL, NULL, 'Гель с арктическими водорослями, пантенолом и коллагеном глубоко и бережно очищает кожу тела. Интенсивно увлажняет и спо- собствует поддержанию водного баланса, обновляет, тонизирует', 'Каталог Siberian Wellness RU 2026, стр. PDF 114', '/admin/uploads/products/catalog-2026/ru-2026-gel-dla-dusa-424407.webp', NULL, 1, 'approved', 1, 1370) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(sourc