INSERT INTO products (category_id, title, slug, catalog_sku, catalog_source, catalog_page, product_kind, safety_review_status, image_review_status, recommendation_notice, short_description, full_description, composition, warning_text, allowed_claims, source_urls, image_path, price, ai_enabled, content_status, is_active, sort_order) VALUES ((SELECT id FROM product_categories WHERE slug = 'body-care' LIMIT 1), 'КРЕМ ДЛЯ ТЕЛА', 'ru-2026-krem-dla-tela-424408', '424408', @catalog_source, 114, 'personal_care', 'not_required', 'candidate', 'Подбор выполнен по информации и предпочтениям клиента. Учитывайте индивидуальную чувствительность.', 'Увлажняющий крем с арктиче- скими водорослями, витамином Е и эластином повышает упругость кожи. Способствует активации кровообращения, выработке коллагена и эластина, снятию отечности и выведению токсинов, оказывает эффект лифтинга.', 'баланса, обновляет, тонизирует, повышает упругость, смягчает и успокаивает. 250 мл 630 ₽ КРЕМ ДЛЯ ТЕЛА Увлажняющий крем с арктиче- скими водорослями, витамином Е и эластином повышает упругость кожи. Способствует активации кровообращения, выработке коллагена и эластина, снятию отечности и выведению токсинов, оказывает эффект лифтинга. 250 мл 660 ₽', NULL, NULL, 'Увлажняющий крем с арктиче- скими водорослями, витамином Е и эластином повышает упругость кожи. Способствует активации кровообращения, выработке коллагена и эластина, снятию отечности и выведению токсинов, оказывает эффект лифтинга.', 'Каталог Siberian Wellness RU 2026, стр. PDF 114', '/admin/uploads/products/catalog-2026/ru-2026-krem-dla-tela-424408.webp', NULL, 1, 'approved', 1, 1371) ON DUPLICATE KEY UPDATE title = VALUES(title), category_id = VALUES(category_id), catalog_sku = VALUES(catalog_sku), catalog_source = VALUES(catalog_source), catalog_page = VALUES(catalog_page), product_kind = VALUES(product_kind), safety_review_status = VALUES(safety_review_status), image_review_status = VALUES(image_review_status), recommendation_notice = VALUES(recommendation_notice), short_description = VALUES(short_description), full_description = VALUES(full_description), composition = VALUES(composition), warning_text = VALUES(warning_text), allowed_claims = VALUES(allowed_claims), source_urls = VALUES(source_urls), image_path = VALUES(image_path), price = VALUES(price), ai_enabled = VALUES(ai_enabled), content_status = VALUES(content_status), is_active = 1;
